import ifj26.*

def printLine(value: String): Unit =
  print(value)
  print("\n")

def range(i: Int, j: Int): List[Int] = (i until j).toList

def count(list: List[Int]): Int =
  var total = 0
  for i <- list do
    total =  total + 1

  return total

def first(list: List[Int]): Int =
  if count(list) > 0 then
    return list(0)
  else
    return 0

def last(list: List[Int]): Int =
  var i = count(list)
  if i > 0 then
    return list(i - 1)
  else
    return 0

def sum(list: List[Int]): Int =
  var total = 0
  for i <- list do
    total = total + i
  return total


